1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: QuoteStep[];
20	};
21	
22	export type ScenarioResult = {
23	  results: unknown[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	
29	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
30	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
31	
32	/** The item types the MHPCO will insure, and what each costs to cover. */
33	const BASE_PREMIUMS: Record<string, number | undefined> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	/** Premium for a single item of this type. `undefined` for a type the MHPCO does not insure — rejecting those is not yet specified by a test. */
43	const unitPremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];
44	
45	/** Component types that form discounted blocks. */
46	const BLOCK_FORMING_COMPONENTS = new Set(["rune", "moonstone"]);
47	const COMPONENT_BLOCK_SIZE = 3;
48	const COMPONENT_BLOCK_PREMIUM = 60;
49	
50	const formsComponentBlock = (type: string, count: number): boolean =>
51	  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;
52	
53	const countByType = (items: Item[]): Map<string, number> => {
54	  const counts = new Map<string, number>();
55	  for (const item of items) {
56	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
57	  }
58	  return counts;
59	};
60	
61	/** Alike components form a discounted block; everything else is priced per unit. */
62	const basePremiumForGroup = (type: string, count: number): number => {
63	  if (formsComponentBlock(type, count)) return COMPONENT_BLOCK_PREMIUM;
64	  const unitPremium = unitPremiumFor(type);
65	  // An uninsurable type yields NaN, which propagates to the quote. Rejecting
66	  // unknown types with a real error is specified by a test we have not reached yet.
67	  return unitPremium === undefined ? NaN : count * unitPremium;
68	};
69	
70	const policyBasePremium = (items: Item[]): number =>
71	  [...countByType(items)].reduce(
72	    (total, [type, count]) => total + basePremiumForGroup(type, count),
73	    0,
74	  );
75	
76	const CURSE_SURCHARGE_RATE = 0.5;
77	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	
80	/** Each risk an item can carry, and the surcharge rate it attracts. */
81	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
82	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
83	  {
84	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
85	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
86	  },
87	];
88	
89	/** Item-level surcharge rates stack additively on one item. */
90	const surchargeRateFor = (item: Item): number =>
91	  ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).reduce(
92	    (rate, rule) => rate + rule.rate,
93	    0,
94	  );
95	
96	/**
97	 * Item-level surcharges apply to the affected item's own base premium, not to
98	 * the policy total. An uninsurable type yields NaN and propagates to the quote,
99	 * as in `basePremiumForGroup`.
100	 */
101	const itemSurchargeTotal = (items: Item[]): number =>
102	  items.reduce(
103	    (total, item) => total + (unitPremiumFor(item.type) ?? NaN) * surchargeRateFor(item),
104	    0,
105	  );
106	
107	const LOYALTY_DISCOUNT_RATE = 0.2;
108	const LOYALTY_YEARS_THRESHOLD = 2;
109	
110	/**
111	 * Policy-level modifiers are percentages of the policy base premium and stack
112	 * additively, per the MHPCO's worked examples.
113	 */
114	const policyModifierRate = (customer: Customer): number => {
115	  const loyalty = customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? -LOYALTY_DISCOUNT_RATE : 0;
116	  return loyalty + FIRST_INSURANCE_SURCHARGE;
117	};
118	
119	const quotePremium = (items: Item[], customer: Customer): number => {
120	  const policyBase = policyBasePremium(items) + itemSurchargeTotal(items);
121	  const withPolicyModifiers = policyBase * (1 + policyModifierRate(customer));
122	  const withProcessingFee = withPolicyModifiers + PROCESSING_FEE;
123	  return roundUpToWholeG(withProcessingFee);
124	};
125	
126	export const runScenario = (scenario: Scenario): ScenarioResult => {
127	  return {
128	    results: scenario.steps.map((step) => ({
129	      premium: quotePremium(step.items, scenario.customer),
130	    })),
131	  };
132	};
